<template><view v-show="props.visible" class="cw-dialog" role="dialog" aria-label="调整会员时长" @tap.self="emit('close')"><view class="cw-dialog-panel"><text class="cw-subtitle">调整会员时长</text><text class="cw-scope">{{ props.permanent?'此用户为永久会员，当前不可调整时长。':`当前剩余有效天数：${props.days??0}；结果按服务端实际有效期重新读取。` }}</text><label class="cw-form-field"><text>调整方向</text><picker :range="directions" range-key="name" :value="direction==='add'?0:1" :disabled="props.busy||props.permanent" @change="direction=Number($event.detail.value)===0?'add':'subtract'"><view>{{ direction==='add'?'增加':'减少' }}</view></picker></label><label class="cw-form-field"><text>天数</text><input v-model="value" type="number" :disabled="props.busy||props.permanent" placeholder="1至999999的整数" aria-label="会员调整天数" /></label><text v-if="localError||props.error" class="cw-error">{{ localError||props.error }}</text><view class="cw-dialog-buttons"><button :disabled="props.busy" @tap="emit('close')">取消</button><button :disabled="props.busy||props.permanent" @tap="submit">确认调整</button></view></view></view></template>
<script setup lang="ts">
import { ref,watch } from 'vue';import { customerWorkUserPositive } from '@/utils/customerWorkUsersContract';
const props=defineProps<{visible:boolean;permanent:boolean;days:number|null;busy:boolean;error:string}>(),emit=defineEmits<{close:[];submit:[payload:{direction:'add'|'subtract';days:number}]} >();
const directions=[{name:'增加'},{name:'减少'}],direction=ref<'add'|'subtract'>('add'),value=ref(''),localError=ref('');watch(()=>props.visible,()=>{direction.value='add';value.value='';localError.value='';},{immediate:true});
function submit(){if(props.busy||props.permanent)return;try{emit('submit',{direction:direction.value,days:customerWorkUserPositive(value.value,999999)});}catch(failure){localError.value=failure instanceof Error?failure.message:'天数无效';}}
</script>
